{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Alfentanil, the closest retrieved analogue (Morgan similarity 0.6154), has baseline absolute oral bioavailability 0.45 ± 0.09 in healthy subjects, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Fentanyl, the parent 4-anilinopiperidine scaffold, has absolute oral bioavailability 0.32 ± 0.1 after oral solution administration, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Pethidine, another 4-anilinopiperidine opioid, has absolute oral bioavailability 0.52 in healthy subjects, reinforcing the pattern of moderate-to-high oral F in this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Phenoperidine, a more distant analogue, shows low systemic bioavailability (~9.9–13.9%) after oral dosing, providing a contradictory example; its lower similarity and ester-containing structure reduce transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a fentanyl/alfentanil-type 4-anilinopiperidine. The closest analogue alfentanil has baseline oral F ~0.33–0.45, fentanyl ~0.32, and pethidine ~0.52, all above the 20% threshold. Lower-similarity low-F examples are structurally divergent and outweighed by the higher-transfer evidence. Prediction: high.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself.",
    "Potential first-pass metabolism differences due to the thiophene side chain versus alfentanil's tetrazole side chain are not directly quantified.",
    "Most alfentanil low-F records were obtained under rifampin enzyme induction and are not applicable to baseline conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

